    quadraticVoting: 'क्वाड्रेटिक वोटिंग',
    quadraticDesc: 'व्हेल डोमिनेंस कम करने के लिए:',
    quadratic1: 'हम क्वाड्रेटिक वोटिंग का उपयोग करते हैं प्रमुख मॉडरेशन निर्णयों के लिए।',
    quadratic2: 'उदाहरण: वोटिंग पावर = √(स्टेक किए गए टोकन)',
    quadratic3: 'इसलिए, 100 टोकन स्टेक करना = 10 वोट, 10,000 टोकन स्टेक करना = 100 वोट (नहीं, 10,000 वोट)।',
    modStakingPools: 'मॉडरेशन स्टेकिंग पूल्स',
    modStaking1: 'यूज़र्स टोकन स्टेक कर सकते हैं मॉडरेटर बनने के लिए।',
    modStaking2: 'हर फ्लैग किए गए कंटेंट को एक मॉडरेशन क्यू में डाल दिया जाता है।',
    modStaking3: 'स्टेकर्स निर्णय (बन, वार्न, इग्नोर, आदि) पर वोट देते हैं।',
    modStaking4: 'सही वोट (अंतिम परिणाम के अनुसार) पुरस्कार अर्जित करते हैं; गलत वोट से स्लैशिंग हो सकती है।',
    modStakingIncentive: 'स्टेक = गेम में स्किन। उच्च गुणवत्ता वाला मॉडरेशन = अधिक पुरस्कार।',
    delegatedMod: 'डिलिगेटेड मॉडरेशन (स्केलिंग के लिए)',
