    delegated2: 'क्युरेटर्स/मॉडरेटर्स को कभी भी स्वैप किया जा सकता है।',
    delegated3: 'यह पासिव यूज़र्स को गवर्नेंस में भाग लेने की अनुमति देता है जबकि एक्टिव यूज़र्स को पुरस्कृत करता है।',
    contentTiering: 'कंटेंट टियरिंग क्युरेशन मार्केट्स के माध्यम से',
