    feedsTitle: 'फ़ीड और सामग्री कैलकुलेटर',
    feedsDesc: 'DeHub होम सतह एक एकल टैब फ़ीड है जो एक ही समय में प्रत्येक सामग्री प्रारूप को ले जाता है । एक माध्यम में रचनाकारों को मजबूर करने के बजाय, फ़ीड पाठ, छवियों, लंबी आकार के वीडियो, शॉर्ट - फॉर्म रील, संगीत और लाइव स्ट्रीम को एक स्क्रॉल में मिलाता है, और दर्शकों को एक एकल प्रारूप में संकीर्ण करता है जब वे चाहते हैं । प्रत्येक कार्ड, चाहे कोई भी प्रारूप हो, एक ही सामाजिक और मुद्रीकरण नियंत्रण लेता हैः जैसे, टिप्पणी, पुनः पोस्ट, उद्धरण, बुकमार्क और टिप में DeHub टोकन ।',
    feedsDesc2: 'फार्मूला फ़ीड के ऊपरी भाग में टैब के रूप में उभरता है । डिफ़ॉल्ट होम टैब आपके अनुसरण करे वाला लोग और समुदायों से सब कुछ जोड़ता है; समर्पित टैब एक माध्यम को अलग करता है ताकि आप, उदाहरण के लिए, केवल लंबी आकार के वीडियो या केवल संगीत ब्राउज़ कर सकें । रैंकिंग प्लेटफॉर्म लीडरबोर्ड एल्गोरिथ्म द्वारा संचालित हय जे इ पृष्ठ के आगे प्रलेखित हय, इसलिए गुणवत्ता और जुड़ाव, विज्ञापन खर्च के बजाय, REACH तय करो हय ।',
