    studioB4: 'एक योजना के रूप में या एक योजना के रूप में देय लाभः',
    arcadeTitle: 'अर्जेंटीना, अर्जेंटीना',
    arcadeDesc2: 'इनमें से दो भी उपस्थिति विषयों के भीतर छिपे हैंः ऐप को युद्ध के लिए सेट करें और क्लाउड ऑफ ड्यूटी स्वयं विषय से पहुंच योग्य है, और जंगल थीम जंगल ट्रेल को छिपाता है । किंग्स गाम्बिट और स्ट्रीट स्लेयर लीडरबोर्ड रखो हय, और प्रत्येक गेम के अपन शेयर कार्ड होवो हय, ताकि आप एकरा सही ढंग से कहीं भी पोस्ट कर सको ।',
