    tocArticles: 'लेख अउर कथ्य',
    articlesTitle: 'लेख अउर कथ्य',
    articlesDesc: 'लंबे समय से प्रतीक्षित कविता के अपन तरीका होवो हय । Post से Article में संगीतकार को स्विच करें और आपको एक शीर्षक, 20,000 वर्ण तक के एक बॉडी, एक स्वरूपन टूलबार, एक कवर छवि और एक पूर्वावलोकन मिलता है कि यह कैसे पढ़ता है । एगो लेख कोनो दोसर पोस्ट के तरह प्रकाशित करई हई, येहिलेल एकरा टिप, उद्धृत, गेट अउर साझा कैल जा सकई हई, अउर जब लिंक दोसर जगह पोस्ट कैल जाई हई त एकरा अपन साझा कार्ड मिलई छई ।',
    articlesB1Desc: 'टूलबार से शीर्षक, जोर, सूचियों और लिंक, प्रकाशित करने से पहले पूर्वावलोकन के साथ ।',
    articlesB2: 'फोटो गेलरी:',
