    multipostB1: 'हल: (e) तीन से अधिक',
    multipostB1Desc: 'एक्स, इंस्टाग्राम, फेसबुक, यूट्यूब, टिक टॉक, लिंक्डइन, थ्रेड्स, पिनटेरेस्ट, रेडिट, गूगल बिजनेस, स्नैपचैट, डिस्कॉर्ड और फार्कास्टर । फ़ार्केस्टर पोस्ट एक हस्ताक्षरकर्ता के माध्यम से जाता है जो आप Farcaster App में अनुमोदित करते हैं ।',
    multipostB2: 'उधारदारों के हलफनामे मेंः',
