    communitiesB2Desc: 'प्रत्येक समुदाय में एक समर्पित फ़ीड और चैट होवो हय जहां सदस्य पोस्ट करो हय, चर्चा करो हय, मतदान करो हय, @उल्लेख करो हय और सुझाव, समुदाय के मालिक द्वारा संचालित होवो हय ।',
    walletHubB1Desc: 'ईटीएच, बीएनबी, यूएसडीटी, यूएसडीसी और बेस, बीएनबी चेन, एथेरियम, रॉबिनहुड चेन और आर्क के साथ - साथ आपके सोलाना होल्डिंग्स के साथ एक बहु - चेन वॉलेट होल्डिंग डीहब टोकन । शून्य संतुलन छिपा है, और ऐप पूछता है कि आप एक पता कॉपी करने से पहले कौन सा नेटवर्क मतलब है । प्राप्त करें, भेजें, खरीदें, व्यापार, हिस्सेदारी, पुल और कैश आउट सब कुछ शेष से एक नल है ।',
