    walletHubB5: 'हल्द्वानी: हल्द्वानी',
    walletHubB5Desc: 'सेटिंग्स में एक सोलाना वॉलेट जोड़ें ताकि इसके होल्डिंग्स को दूसरे सब कुछ के बगल में देख सकें और बृहस्पति के माध्यम से उन्हें ट्रेड कर सकें ।',
    tocExchange: 'विनिमय',
    exchangeTitle: 'विनिमय',
    exchangeDesc: 'Dehub.io/dex पर Dehub.io के अपन एक्सचेंज हय । DeHub टोकन पृष्ठ प्रत्येक पूल, एक लाइव चार्ट, बेस पर सीमा आदेशों के एक आदेश पुस्तक, हालिया व्यापार और तत्काल खरीद और बिक्री पर एक मूल्य दिखाता है । आपके खुली पोजीशन मेरी पोजीशन के तहत सूचीबद्ध हैं, और BnB Chain पर पुराने पोजीशन वहां दिखाई देते हैं ताकि आप उन्हें वापस ले सकें ।',
    exchangeB1: 'हल्की ट्रेडिंगः',
    exchangeB1Desc: 'ट्रेडिंग बटन आसान ट्रेडिंग या पूर्ण एक्सचेंज प्रदान करता है । आसान ट्रेडिंग तीन चरणों में DeHub टोकन बेचता है — मात्रा, कीमत, पुष्टि । बाजार मूल्य पर या उससे कम पर यह तुरंत बिकता है; उसके ऊपर, आपकी ऑर्डर पुस्तक में सूचीबद्ध है । आप व्यापार को एक वाक्य के रूप में भी टाइप कर सकते हैं और AI को इसे भरने दें ।',
    exchangeB2: 'किसी भी हलचल के लिए हलचलः',
    exchangeB2Desc: 'कोई भी बेस, एथेरियम, रॉबिनहुड चेन या सोलाना पर एक टोकन के लिए एक पूल खोल सकता है $ 100 के लिए, DeHub टोकन में भुगतान की गई । प्रत्येक पूल के पास एक चार्ट, एक ऑर्डर बुक और तत्काल खरीद और बिक्री के साथ अपने स्वयं की पृष्ठ है, और निर्माता अपनी छवि सेट कर सकता है ।',
    exchangeB3: 'जितना चाहे कर लो पेमेंटः',
    exchangeB3Desc: 'एक खरीद आदेश ETH, USDC या USDT के साथ भुगतान की जा सकती है । BNB के धारकों को बेस पर ETH में एक - टैप रूपांतरण मिलता है ।',
    tocMarkets: 'बजार हल्ला बोल - हल्ला बोल',
    marketsTitle: 'उपयोगकर्ता नाम, कैलकुलेटर और अंश',
    marketsDesc: 'तीन मार्केटप्लेस आपको DeHub पर खरीदे और बेचने के लिए अनुमति देता है, DeHub टोकन में भुगतान की गई है ।',
    marketsB1: 'हय का प्रयोगः',
    marketsB1Desc: 'Dehub.io/usernames पर, फिक्स्ड डॉलर की कीमतों पर बिक्री के लिए हैंडल ब्राउज़ करें, जो चाहें वो खोजें, और इसे खरीदें । कोई अपना खाता बनवा सकता है, चाहे वो एयरटेल का खाता हो या ना हो. एक नाम जेकर अर्थ हय दो अलग - अलग चीजें एक समानार्थी हय । यदि कोई नाम केवल अनचाहे है, तो पृष्ठ इसे बेचने के बजाय ऐसा कहता है ।',
    marketsB2: 'कैलकुलेटर:',
